<?php require_once __DIR__ . '/includes/functions.php'; $count=(int)db()->query('SELECT COUNT(*) FROM admins')->fetchColumn(); if($count>0 && empty($_SESSION['admin_id'])){http_response_code(403);exit('Admin registration is closed. An existing administrator can add access through secure setup.');} if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['full_name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$name||!$email||strlen($pw)<10||$pw!==($_POST['confirm_password']??'')){flash('error','Use a valid name and email. Passwords must match and be at least 10 characters.');}else{try{$s=db()->prepare('INSERT INTO admins(full_name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);flash('success','Administrator created. Please sign in.');header('Location: login.php');exit;}catch(PDOException $e){flash('error','That email is already registered.');}}} $page_title='Secure admin setup';require 'includes/header.php';?><section class="section"><div class="container auth-card"><p class="eyebrow">Secure setup</p><h1><?= $count?'Add administrator':'Create the first administrator' ?></h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Full name<input required name="full_name"></label><label>Email<input required type="email" name="email"></label><label>Password<input required type="password" name="password" minlength="10"></label><label>Confirm password<input required type="password" name="confirm_password" minlength="10"></label><button class="button primary">Create account</button></form></div></section><?php require 'includes/footer.php'; ?>
